  const pineParts=[];for(let k=0;k<5;k++){let r=1.65-k*.27,h=2.8-k*.24,pg=new T.ConeGeometry(r,h,10,3);pg.translate(0,1.8+k*1.14,0);let pos=pg.attributes.position;for(let i=0;i<pos.count;i++){let x=pos.getX(i),y=pos.getY(i),z=pos.getZ(i),v=1+noise(x*6+k,z*6-y)*.13;pos.setXYZ(i,x*v,y,z*v)}pg.computeVertexNormals();pineParts.push(pg)}let pineGeo=join(pineParts),pineRows=[];for(let i=0;i<640;i++){let x=-440+rnd()*780,z=-145-rnd()*185;if(noise(x*.08,z*.07)<-.22)continue;pineRows.push({x,z})}let pine=new T.InstancedMesh(pineGeo,new T.MeshLambertMaterial({color:0xffffff}),pineRows.length);pineRows.forEach((p,i)=>{let blend=smooth(-150,-350,p.z),y=groundHeight(p.x,p.z)+blend*(13+Math.sin(p.x*.012)*8+noise(p.x*.027,p.z*.02)*8);dummy.position.set(p.x,y-.6,p.z);dummy.rotation.set(0,rnd()*TAU,0);dummy.scale.setScalar(.65+rnd()*.75);dummy.updateMatrix();pine.setMatrixAt(i,dummy.matrix);pine.setColorAt(i,color.set(['#60856a','#597c6a','#719078','#668b72'][i%4]))});pine.castShadow=false;pine.receiveShadow=false;scene.add(pine);
