function heartTexture(){let c=document.createElement('canvas');c.width=c.height=128;let x=c.getContext('2d'),grad=x.createLinearGradient(25,20,102,108);grad.addColorStop(0,'#c3d994');grad.addColorStop(.4,'#88ad5c');grad.addColorStop(1,'#4e7d42');x.fillStyle=grad;x.beginPath();x.moveTo(64,116);x.bezierCurveTo(45,81,4,65,15,34);x.bezierCurveTo(21,9,52,8,64,30);x.bezierCurveTo(76,8,109,8,115,35);x.bezierCurveTo(125,65,83,84,64,116);x.fill();x.strokeStyle='#dce7b266';x.lineWidth=2;x.beginPath();x.moveTo(64,108);x.lineTo(64,32);for(let i=0;i<4;i++){let y=45+i*13;x.moveTo(64,y+17);x.lineTo(30,y-2);x.moveTo(64,y+17);x.lineTo(98,y-2)}x.stroke();let t=new T.CanvasTexture(c);t.colorSpace=T.SRGBColorSpace;return t}
